{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    for key in ("nodes", "required_symbols"):
        if key not in case:
            raise ValueError("missing required field: " + key)

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise TypeError("nodes must be an array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise TypeError("required_symbols must be an array of strings")

    required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    by_id = {}
    order = []
    for node in nodes:
        if not isinstance(node, dict):
            raise TypeError("each node must be an object")
        for key in required_fields:
            if key not in node:
                raise ValueError("missing required node field: " + key)
        node_id = node["id"]
        parent = node["parent"]
        if not isinstance(node_id, str):
            raise TypeError("node id must be a string")
        if parent is not None and not isinstance(parent, str):
            raise TypeError("node parent must be null or a string")
        if not isinstance(node["symbol"], str):
            raise TypeError("node symbol must be a string")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int) or node["depth"] < 0:
            raise TypeError("node depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise TypeError("node removable must be boolean")
        if isinstance(node["utility"], bool) or not isinstance(node["utility"], (int, float)):
            raise TypeError("node utility must be numeric")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        by_id[node_id] = node
        order.append(node_id)

    roots = [node_id for node_id in order if by_id[node_id]["parent"] is None]
    if len(roots) != 1:
        raise ValueError("the tree must have exactly one root")
    for node_id in order:
        parent = by_id[node_id]["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("node parent does not exist")

    symbol_counts = {}
    for node in by_id.values():
        symbol_counts[node["symbol"]] = symbol_counts.get(node["symbol"], 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required_symbols):
        raise ValueError("required symbol is not represented")

    children = {node_id: [] for node_id in order}
    for node_id in order:
        parent = by_id[node_id]["parent"]
        if parent is not None:
            children[parent].append(node_id)

    retained = set(order)
    removed = []
    required = set(required_symbols)
    candidates = sorted(
        (by_id[node_id] for node_id in order if by_id[node_id]["removable"]),
        key=lambda node: (-node["depth"], node["id"])
    )

    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node["parent"] is None or node_id == "root":
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbol_counts[node["symbol"]] -= 1
        if any(symbol_counts.get(symbol, 0) == 0 for symbol in required):
            symbol_counts[node["symbol"]] += 1
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }"}
